\begin{itemchoice}
			\itemch Ta có: $f'(x) = 3x^2 - 3$.
			\itemch $f'(x) = 0 \Leftrightarrow 3x^2 - 3 = 0 \Leftrightarrow \left[ \begin{array}{l} x = 1 \\ x = -1 \end{array} \right.$.\\
			Vậy phương trình $f'(x) = 0$ có tập nghiệm là $S = \{-1; 1\}$.
			\itemch $f(1) = -1$, $f(-1) = 3$.
			\itemch $f'(x) = 0 \Leftrightarrow \left[ \begin{array}{l} x = 1 \Rightarrow f(x) = -1 \\ x = -1 \Rightarrow f(x) = 3 \end{array} \right.$.\\
			Ta có bảng biến thiên sau:
			\begin{center}
				<img src='HinhAnh/sol_9ef992499d_lg_tikz_1.png' style='max-width: 100%; height: auto; display: block; margin: 10px auto;' />
			\end{center}
			Vậy hàm số có $f_{\text{CĐ}} = 3$ và $f_{\text{CT}} = -1$, $f_{\text{CĐ}} - f_{\text{CT}} = 4$.
		\end{itemchoice}
